SCRIPTS = SKILL / "scripts"
sys.path.insert(0, str(SCRIPTS))


def make_pe(text=b"\xAA\xBB\xCC\xDD" + bytes(range(60)), image_base=0x400000) -> bytes:
    """A minimal 32-bit PE: one .text section at RVA 0x1000, raw offset 0x400."""
    dos = bytearray(0x80)
    dos[0:2] = b"MZ"
    struct.pack_into("<i", dos, 0x3C, 0x80)
    coff = b"PE\0\0" + struct.pack("<HHIIIHH", 0x14C, 1, 1114702282, 0, 0, 0xE0, 0x10F)
    opt = bytearray(0xE0)
    struct.pack_into("<H", opt, 0, 0x10B)
    struct.pack_into("<I", opt, 16, 0x1000)
    struct.pack_into("<I", opt, 28, image_base)
    struct.pack_into("<III", opt, 56, 0x3000, 0x400, 0)
    section = b".text\0\0\0" + struct.pack("<IIII", 0x1000, 0x1000, 0x200, 0x400) + bytes(16)
    head = bytes(dos) + coff + bytes(opt) + section
    return head.ljust(0x400, b"\0") + text.ljust(0x200, b"\0")


def make_install(base: Path, exe=None) -> Path:
    game = base / "Game"
    (game / "data" / "maps" / "area").mkdir(parents=True)
    (game / "data" / "script").mkdir(parents=True)
    (game / "models").mkdir()
    (game / "text").mkdir()
    (game / "gta_sa.exe").write_bytes(exe if exe is not None else make_pe())
    (game / "data" / "script" / "main.scm").write_bytes(b"scm-fixture")
    (game / "data" / "handling.cfg").write_bytes(b"cfg-fixture")
    (game / "models" / "gta3.img").write_bytes(b"img-fixture")
    return game


