def write_ipl(game: Path, name: str, body: str) -> Path:
    path = game / "data" / "maps" / "area" / name
    path.write_bytes(body.replace("\n", "\r\n").encode("latin-1"))
    return path


LAUNCHER = (sys.executable,)  # the stand-in is a Python file named sanny.exe, started through the interpreter


def make_stub_sanny(folder: Path, behaviour="ok") -> Path:
    """A stand-in for sanny.exe that records its arguments and the settings it saw (any operating system)."""
    folder.mkdir(parents=True, exist_ok=True)
    stub = folder / "sanny.exe"
    stub.write_text(
        "import json, os, sys, time\n"
        "here = os.path.dirname(os.path.abspath(__file__))\n"
        "ini = os.path.join(here, 'data', 'settings.ini')\n"
        "seen = open(ini, 'rb').read().decode('latin-1') if os.path.exists(ini) else None\n"
        "json.dump({'argv': sys.argv[1:], 'settings': seen}, open(os.path.join(here, 'call.json'), 'w'))\n"
        "mode = %r\n"
        "if mode == 'hang': time.sleep(30)\n"
        "if mode == 'fail': sys.exit(3)\n"
        "if mode == 'silent': sys.exit(0)\n"
        "open(sys.argv[3], 'w').write(':MAIN_1\\n0001: wait 0\\n')\n" % behaviour, encoding="utf-8")
    return stub
